  "items": [
    {
      "original_text": "A session-start hook scans all git-tracked files, counts files per directory, and identifies directories exceeding the configured threshold",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability that runs continuously on session start, not a one-time migration task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Directories matching .gitignore entries (via git ls-files), .git/, and a configurable exclusion list in dso-config.conf are excluded from scanning",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior of what gets excluded during scanning operations"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a directory exceeds the threshold and no open ticket tagged dir:<path> exists, a P4 epic is auto-created with a descriptive title and the dir:<path> tag",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing automated system behavior that will be true after implementation and remain durable"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "No duplicate tickets are created for the same directory \u2014 deduplication checks open tickets only, allowing re-flagging after a previous ticket is closed",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior about how duplicate detection works, phrased as a durable property of the ticket creation process"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The hook prints an advisory summary of flagged directories to stderr without blocking session startup",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior (hook printing behavior) that persists after implementation, not a one-time completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Threshold and exclusion list are configurable via dso-config.conf keys (directory_monitor.file_threshold default 30, directory_monitor.exclude_dirs default .git)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability where configuration properties are persistently accessible and functional after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When the directory monitor is active, starting a new session in a repo where tests/scripts/ has 351 files produces an advisory notice listing that directory as oversized\n<- Satisfies: \"A session-start hook scans all git-tracked files, counts files per directory, and identifies directories exceeding the configured threshold\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior (advisory notice generation) that persists after the work is complete, not a one-time task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When the monitor detects an oversized directory with no existing open dir:<path> ticket, a new P4 epic appears in the ticket system with the dir:<path> tag\n<- Satisfies: \"When a directory exceeds the threshold and no open ticket tagged dir:<path> exists, a P4 epic is auto-created\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing automated system behavior that persists after implementation, not a one-time completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a dir:<path> ticket already exists and is open, starting a new session does not create a duplicate ticket for that directory\n<- Satisfies: \"No duplicate tickets are created for the same directory\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes an ongoing system behavior (duplicate prevention) that persists after implementation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When directory_monitor.file_threshold is set to 50 in dso-config.conf, directories with 40 files are not flagged\n<- Satisfies: \"Threshold and exclusion list are configurable via dso-config.conf\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where a specific configuration setting produces consistent monitoring behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When directory_monitor.exclude_dirs includes a directory path, that directory is not flagged regardless of file count\n<- Satisfies: \"Directories matching .gitignore entries, .git/, and a configurable exclusion list are excluded\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior where excluded directories are persistently not flagged after configuration"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When the monitor runs, directories covered by .gitignore (like node_modules/) are not counted\n<- Satisfies: \"Directories matching .gitignore entries (via git ls-files) are excluded\"",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior where the monitor persistently excludes gitignore directories during operation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
